"""v31: worked examples for every 'new here' feature. Each entry: (explanation, setup, [expressions]).
Setup lines after a line '#show' are printed in the note as the example's code; lines before it run silently
(imports, a small table). Every expression is evaluated by build.py with the same numpy, pandas and
scikit-learn versions as the in-browser Python, and its real value is shown."""

SQL = ("import sqlite3\ncon = sqlite3.connect(':memory:')\n"
       "con.execute('CREATE TABLE t (agency TEXT, hours REAL)')\n"
       "con.executemany('INSERT INTO t VALUES (?, ?)', [('DOT', 2), ('DOT', 6), ('DEP', None)])\n")
SQL_NOTE = " The example uses a table <code>t</code> with three rows: (DOT, 2), (DOT, 6) and (DEP, NULL)."
SK_DATA = "X = [[0], [1], [2], [3], [8], [9], [10], [11]]\ny = [0, 0, 0, 0, 1, 1, 1, 1]\n"

